def is_alternating_case(s):
    letters = [c for c in s if c.isalpha()]
    for i in range(1, len(letters)):
        if letters[i].isupper() == letters[i - 1].isupper():
            return False
    return True

def modified_competition_rank(nums):
    s = sorted(nums)
    rank_map = {}
    for i, v in enumerate(s):
        rank_map[v] = i + 1
    return [rank_map[x] for x in nums]

def count_bigrams(text):
    words = text.split()
    d = {}
    for i in range(len(words) - 1):
        key = words[i] + " " + words[i + 1]
        d[key] = d.get(key, 0) + 1
    return d

def render_template(template, values):
    result = template
    for k, v in values.items():
        result = result.replace('{' + k + '}', str(v))
    return result

def is_subsequence(s1, s2):
    it = iter(s2)
    return all(ch in it for ch in s1)

def is_valid_sudoku_box(box):
    if len(box) != 9:
        return False
    seen = set()
    for x in box:
        if x == 0:
            continue
        if not (1 <= x <= 9):
            return False
        if x in seen:
            return False
        seen.add(x)
    return True

def is_palindrome_number(n):
    if n < 0:
        return False
    s = str(n)
    return s == s[::-1]

def replace_nth_occurrence(s, ch, n, replacement):
    count = 0
    for i, c in enumerate(s):
        if c == ch:
            count += 1
            if count == n:
                return s[:i] + replacement + s[i + 1:]
    return s

def sum_divisors(n):
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
        i += 1
    return total

def dict_average_values(list_of_dicts):
    sums = {}
    counts = {}
    for d in list_of_dicts:
        for k, v in d.items():
            sums[k] = sums.get(k, 0) + v
            counts[k] = counts.get(k, 0) + 1
    return {k: sums[k] / counts[k] for k in sums}

def sum_of_proper_divisors(n):
    n = abs(n)
    return sum(i for i in range(1, n) if n % i == 0)

def caesar_shift(s, shift):
    out = []
    for ch in s:
        if ch.isalpha():
            base = 65 if ch.isupper() else 97
            out.append(chr((ord(ch) - base + shift) % 26 + base))
        else:
            out.append(ch)
    return ''.join(out)

def replace_digits_with_words(s):
    names = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    out = []
    for ch in s:
        if ch.isdigit():
            out.append(names[int(ch)])
        else:
            out.append(ch)
    return ''.join(out)

def is_balanced_parentheses(s):
    depth = 0
    for ch in s:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

def meets_strict_password_policy(s):
    if len(s) < 10:
        return False
    if any(c.isspace() for c in s):
        return False
    specials = set('!@#$%^&*')
    return (any(c.isupper() for c in s) and any(c.islower() for c in s)
            and any(c.isdigit() for c in s) and any(c in specials for c in s))

def reindent(text, old_n, new_n):
    out = []
    prefix = " " * old_n
    for line in text.split("\n"):
        if line.startswith(prefix):
            out.append(" " * new_n + line[old_n:])
        else:
            out.append(line)
    return "\n".join(out)

def is_balanced_angle_brackets(s):
    depth = 0
    for c in s:
        if c == '<':
            depth += 1
        elif c == '>':
            depth -= 1
            if depth < 0:
                return False
        else:
            return False
    return depth == 0

def difference_preserve_order(a, b):
    bset = set(b)
    result = []
    seen = set()
    for x in a:
        if x not in bset and x not in seen:
            result.append(x)
            seen.add(x)
    return result

def longest_run_above_threshold(lst, t):
    best = 0
    cur = 0
    for x in lst:
        if x >= t:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

def atbash_cipher(s):
    out = []
    for ch in s:
        if ch.isupper():
            out.append(chr(ord('Z') - (ord(ch) - ord('A'))))
        elif ch.islower():
            out.append(chr(ord('z') - (ord(ch) - ord('a'))))
        else:
            out.append(ch)
    return ''.join(out)

def first_and_last_char_same(s):
    if not s:
        return False
    return s[0] == s[-1]

def is_valid_us_phone_number(s):
    if len(s) != 14:
        return False
    if s[0] != '(' or s[4] != ')' or s[5] != ' ' or s[9] != '-':
        return False
    area, mid, last = s[1:4], s[6:9], s[10:14]
    if not (area.isdigit() and mid.isdigit() and last.isdigit()):
        return False
    return area[0] in '23456789'

def meets_length_no_whitespace_policy(s):
    if not (8 <= len(s) <= 32):
        return False
    return not any(c.isspace() for c in s)

def tied_max_keys(d):
    best = max(d.values())
    return sorted(k for k, v in d.items() if v == best)
